 static void Add(Transaction tr,BlockTableRecord b,Entity e){e.ColorIndex=256;b.AppendEntity(e);tr.AddNewlyCreatedDBObject(e,true);}
 static bool In(Extents3d b,double x0,double y0,double x1,double y1)=>b.MinPoint.X>=x0&&b.MaxPoint.X<=x1&&b.MinPoint.Y>=y0&&b.MaxPoint.Y<=y1;
 static ObjectId Layer(Database db,Transaction tr,string name,Color color){var lt=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForRead);if(lt.Has(name))return lt[name];lt.UpgradeOpen();var l=new LayerTableRecord{Name=name,Color=color,LineWeight=LineWeight.LineWeight009};var id=lt.Add(l);tr.AddNewlyCreatedDBObject(l,true);return id;}
 static void Move(Transaction tr,Entity e,Matrix3d matrix){e.UpgradeOpen();double factor=matrix.CoordinateSystem3d.Xaxis.Length;e.TransformBy(matrix);if(e is Dimension dim&&Math.Abs(factor-1)>1e-8){dim.Dimlfac/=factor;dim.RecomputeDimensionBlock(true);}}
 static void Text(Transaction tr,BlockTableRecord ps,string value,double x,double y,double h,ObjectId layer,double rotation=0,double width=95){Add(tr,ps,new MText{Location=new Point3d(x,y,0),Contents=value,TextHeight=h,Width=width,Attachment=AttachmentPoint.MiddleCenter,LayerId=layer,Rotation=rotation});}
 static void Leader(Transaction tr,BlockTableRecord ps,string value,Point2d point,Point2d text,ObjectId layer,double width=78){var ml=new MLeader{ContentType=ContentType.MTextContent,LayerId=layer};Add(tr,ps,ml);ml.MText=new MText{Contents=value,TextHeight=2.1,Width=width,ColorIndex=7,Location=new Point3d(text.X,text.Y,0)};ml.TextLocation=new Point3d(text.X,text.Y,0);int i=ml.AddLeaderLine(new Point3d(point.X,point.Y,0));ml.AddLastVertex(i,new Point3d(text.X,text.Y-2,0));ml.ArrowSize=1.5;ml.LeaderLineColor=Color.FromColorIndex(ColorMethod.ByAci,7);ml.DoglegLength=2;}
 static Point2d ToPaper(Viewport v,Point2d p){var d=(p-new Point2d(v.ViewTarget.X,v.ViewTarget.Y)).RotateBy(v.TwistAngle);return new Point2d(v.CenterPoint.X+(d.X-v.ViewCenter.X)*v.CustomScale,v.CenterPoint.Y+(d.Y-v.ViewCenter.Y)*v.CustomScale);}
 static Point2d ToWorld(Viewport v,Point2d p){var d=new Vector2d((p.X-v.CenterPoint.X)/v.CustomScale+v.ViewCenter.X,(p.Y-v.CenterPoint.Y)/v.CustomScale+v.ViewCenter.Y).RotateBy(-v.TwistAngle);return new Point2d(d.X+v.ViewTarget.X,d.Y+v.ViewTarget.Y);}
 static void Grid(Transaction tr,BlockTableRecord ps,Viewport plan,ObjectId layer,ObjectId labels){double x0=plan.CenterPoint.X-plan.Width/2,x1=x0+plan.Width,y0=plan.CenterPoint.Y-plan.Height/2,y1=y0+plan.Height;var c=new[]{ToWorld(plan,new Point2d(x0,y0)),ToWorld(plan,new Point2d(x1,y0)),ToWorld(plan,new Point2d(x1,y1)),ToWorld(plan,new Point2d(x0,y1))};double a=c.Min(p=>p.X),b=c.Max(p=>p.X),d=c.Min(p=>p.Y),f=c.Max(p=>p.Y);Action<Point2d,Point2d,string> draw=(p,q,s)=>{p=ToPaper(plan,p);q=ToPaper(plan,q);var v=q-p;var hit=new List<Point2d>();if(Math.Abs(v.X)>1e-9)foreach(double x in new[]{x0,x1}){double y=p.Y+(x-p.X)/v.X*v.Y;if(y>=y0&&y<=y1)hit.Add(new Point2d(x,y));}if(Math.Abs(v.Y)>1e-9)foreach(double y in new[]{y0,y1}){double x=p.X+(y-p.Y)/v.Y*v.X;if(x>=x0&&x<=x1)hit.Add(new Point2d(x,y));}if(hit.Count<2)return;Add(tr,ps,new Line(new Point3d(hit[0].X,hit[0].Y,0),new Point3d(hit[1].X,hit[1].Y,0)){LayerId=layer,LineWeight=LineWeight.LineWeight005});foreach(var h in hit.Take(2)){bool side=Math.Abs(h.X-x0)<.1||Math.Abs(h.X-x1)<.1;if(side&&(h.Y-y0<12||y1-h.Y<12)||!side&&(h.X-x0<12||x1-h.X<12))continue;Text(tr,ps,s,side?(Math.Abs(h.X-x0)<.1?x0-3:x1+3):h.X,side?h.Y:(Math.Abs(h.Y-y0)<.1?y0-3:y1+3),1.9,labels,side?Math.PI/2:0,50);}};double step=20;for(double x=Math.Ceiling(a/step)*step;x<b;x+=step)draw(new Point2d(x,d-20),new Point2d(x,f+20),x.ToString("N0",CultureInfo.InvariantCulture).Replace(',',' ')+" mE");for(double y=Math.Ceiling(d/step)*step;y<f;y+=step)draw(new Point2d(a-20,y),new Point2d(b+20,y),y.ToString("N0",CultureInfo.InvariantCulture).Replace(',',' ')+" mN");}
 static void Clip(Transaction tr,BlockReference br,double width,double height){var c=br.Position.TransformBy(br.BlockTransform.Inverse());var points=new Point2dCollection(new[]{new Point2d(c.X-width/200,c.Y-height/200),new Point2d(c.X+width/200,c.Y-height/200),new Point2d(c.X+width/200,c.Y+height/200),new Point2d(c.X-width/200,c.Y+height/200)});var spatial=new SpatialFilter{Definition=new SpatialFilterDefinition(points,Vector3d.ZAxis,0,0,0,true)};br.CreateExtensionDictionary();var ext=(DBDictionary)tr.GetObject(br.ExtensionDictionary,OpenMode.ForWrite);var filter=new DBDictionary();ext.SetAt("ACAD_FILTER",filter);tr.AddNewlyCreatedDBObject(filter,true);filter.SetAt("SPATIAL",spatial);tr.AddNewlyCreatedDBObject(spatial,true);}
 static void ScaleBar(Transaction tr,BlockTableRecord ps,double x,double y,double step,string caption,ObjectId layer){for(int i=0;i<5;i++){var p=new Polyline{LayerId=layer};p.AddVertexAt(0,new Point2d(x+i*10,y),0,0,0);p.AddVertexAt(1,new Point2d(x+(i+1)*10,y),0,0,0);p.AddVertexAt(2,new Point2d(x+(i+1)*10,y+1.3),0,0,0);p.AddVertexAt(3,new Point2d(x+i*10,y+1.3),0,0,0);p.Closed=true;Add(tr,ps,p);if(i%2==0){var h=new Hatch{LayerId=layer};Add(tr,ps,h);h.SetHatchPattern(HatchPatternType.PreDefined,"SOLID");h.AppendLoop(HatchLoopTypes.External,new ObjectIdCollection(new[]{p.ObjectId}));h.EvaluateHatch(true);}}for(int i=0;i<=5;i++)Text(tr,ps,(i*step).ToString("0.#",CultureInfo.InvariantCulture)+(i==5?"m":""),x+i*10,y+3.5,1.8,layer);Text(tr,ps,caption,x+25,y-2.8,1.8,layer);}
 static List<string> ModelSignature(Database db,Transaction tr){var ms=(BlockTableRecord)tr.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(db),OpenMode.ForRead);return ms.Cast<ObjectId>().Select(id=>tr.GetObject(id,OpenMode.ForRead)).Where(e=>e.GetType().Namespace.StartsWith("Autodesk.Civil")).Select(e=>e.Handle+" "+e.GetType().FullName).OrderBy(s=>s).ToList();}
 [CommandMethod("FOURAPI")]
 public void Api(){var db=App.DocumentManager.MdiActiveDocument.Database;var log=new List<string>();using(var tr=db.TransactionManager.StartTransaction()){var ms=(BlockTableRecord)tr.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(db),OpenMode.ForRead);foreach(string kind in new[]{"ProfileView","Alignment","Profile"}){var e=ms.Cast<ObjectId>().Select(id=>tr.GetObject(id,OpenMode.ForRead)).First(o=>o.GetType().Name==kind);log.Add("TYPE "+e.GetType().FullName);foreach(var p in e.GetType().GetProperties().Where(p=>p.Name.Contains("Alignment")||p.Name.Contains("Station")||p.Name.Contains("Elevation")||p.Name=="StyleId"||p.Name.Contains("Surface")))try{log.Add("PROP "+p.Name+"="+p.GetValue(e,null));}catch{}foreach(var m in e.GetType().GetMethods().Where(m=>m.Name.Contains("PointLocation")||m.Name.Contains("FindXY")||m.Name.Contains("ElevationAt")||m.Name=="GetProfileIds"))log.Add("METHOD "+m);if(kind=="ProfileView"){var sid=(ObjectId)typeof(Autodesk.Civil.DatabaseServices.Entity).GetProperty("StyleId").GetValue(e,null);var style=tr.GetObject(sid,OpenMode.ForRead);foreach(var m in style.GetType().GetMethods().Where(m=>m.Name.Contains("DisplayStyle"))){log.Add("STYLE_API "+m);foreach(var p in m.GetParameters())if(p.ParameterType.IsEnum)log.Add("STYLE_ENUM "+string.Join(",",Enum.GetNames(p.ParameterType)));}}}}File.WriteAllLines(Path.Combine(Root,"native-api.txt"),log);}
 static bool Inside(Point2d p,Point2d[] polygon){bool inside=false;for(int i=0,j=polygon.Length-1;i<polygon.Length;j=i++){var a=polygon[i];var b=polygon[j];if((a.Y>p.Y)!=(b.Y>p.Y)&&p.X<(b.X-a.X)*(p.Y-a.Y)/(b.Y-a.Y)+a.X)inside=!inside;}return inside;}
 static void Liner(Transaction tr,BlockTableRecord ps,List<Point2d> points,ObjectId liner,ObjectId backing,ObjectId anno){if(points.Count<2)return;foreach(double offset in Code=="007"?new[]{.25,-.65}:new[]{.25}){var line=new Polyline{LayerId=liner,LineWeight=LineWeight.LineWeight015};for(int i=0;i<points.Count;i++)line.AddVertexAt(i,new Point2d(points[i].X,points[i].Y+offset),0,0,0);Add(tr,ps,line);}var boundary=new Polyline{LayerId=backing};int n=0;foreach(var p in points)boundary.AddVertexAt(n++,new Point2d(p.X,p.Y-.8),0,0,0);foreach(var p in points.AsEnumerable().Reverse())boundary.AddVertexAt(n++,new Point2d(p.X,p.Y-2),0,0,0);boundary.Closed=true;Add(tr,ps,boundary);var h=new Hatch{LayerId=backing};Add(tr,ps,h);h.SetHatchPattern(HatchPatternType.PreDefined,"ANSI31");h.PatternScale=.35;h.AppendLoop(HatchLoopTypes.External,new ObjectIdCollection(new[]{boundary.ObjectId}));h.EvaluateHatch(true);var target=points.OrderBy(p=>p.Y).ElementAt(Math.Min(2,points.Count-1));double tx=Math.Max(65,Math.Min(485,target.X-32));string label=Code=="007"?"GEOMEMBRANAS HDPE 1.5 mm\\PVER DETALLE C":"GEOMEMBRANA HDPE 1.5 mm\\PGEOTEXTIL DE 400 g/m²";Leader(tr,ps,label,target,new Point2d(tx,target.Y-12),anno,98);}
 [CommandMethod("FOURFINAL")]
 public void Final(){System.Diagnostics.Process.GetCurrentProcess().PriorityClass=System.Diagnostics.ProcessPriorityClass.BelowNormal;var doc=App.DocumentManager.MdiActiveDocument;var db=doc.Database;db.Cecolor=Color.FromColorIndex(ColorMethod.ByAci,256);LayoutManager.Current.CurrentLayout=LayoutName;var outdir=Path.Combine(Root,"EntregaFinal");Directory.CreateDirectory(Path.Combine(outdir,"Assets"));foreach(var f in Directory.GetFiles(Path.Combine(Previous,"Assets")))File.Copy(f,Path.Combine(outdir,"Assets",Path.GetFileName(f)),true);var logs=new List<string>();var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue};var metrics=(Dictionary<string,object>)((Dictionary<string,object>)js.DeserializeObject(File.ReadAllText(Path.Combine(Root,"metrics.json"))))[Code];var rim=((object[])metrics["rim"]).Select(p=>(object[])p).Select(p=>new Point2d(Convert.ToDouble(p[0]),Convert.ToDouble(p[1]))).ToArray();
 using(var tr=db.TransactionManager.StartTransaction()){var before=ModelSignature(db,tr);var expected=File.ReadAllLines(Path.Combine(Root,"Informes","civil-"+Code+".txt"));if(!expected.SequenceEqual(before))throw new InvalidOperationException("Diferencia de objetos Civil antes de entregar");var layout=(Layout)tr.GetObject(LayoutManager.Current.GetLayoutId(LayoutName),OpenMode.ForWrite);var ps=(BlockTableRecord)tr.GetObject(layout.BlockTableRecordId,OpenMode.ForWrite);var ents=ps.Cast<ObjectId>().Select(id=>tr.GetObject(id,OpenMode.ForRead)).OfType<Entity>().ToArray();var plan=ents.OfType<Viewport>().Single(v=>v.Width>480&&v.Width<500&&v.CenterPoint.Y>400);var profile=ents.OfType<Viewport>().Single(v=>v.Width>560&&v.Width<580&&v.CenterPoint.Y<350);var clipped=new HashSet<ObjectId>(ents.OfType<Viewport>().Where(v=>v.NonRectClipOn).Select(v=>v.NonRectClipEntityId));
 // Remove the old section frame that crosses the notes/table column.
 foreach(var p in ents.OfType<Polyline>()){if(clipped.Contains(p.ObjectId))continue;try{var b=p.GeometricExtents;if(p.Closed&&b.MaxPoint.X-b.MinPoint.X>500&&b.MinPoint.Y>80&&b.MaxPoint.Y<375){p.UpgradeOpen();p.Erase();logs.Add("MARCO AUXILIAR RETIRADO "+p.Handle);}}catch{}}
 // Separate geographic labels which meet too close on the same viewport edge.
 var labelEntities=ents.OfType<MText>().Where(e=>e.Layer=="SOTRAMI_"+Code+"_COORDENADAS").OrderBy(e=>e.Location.X).ThenBy(e=>e.Location.Y).ToArray();var used=new List<Point3d>();foreach(var m in labelEntities){bool collision=used.Any(p=>(Math.Abs(p.X-m.Location.X)<.01||Math.Abs(p.Y-m.Location.Y)<.01)&&p.DistanceTo(m.Location)<30);if(collision){m.UpgradeOpen();m.Erase();}else used.Add(m.Location);}
 var anno=Layer(db,tr,"SOTRAMI_"+Code+"_DETALLES",Color.FromColorIndex(ColorMethod.ByAci,7));var liner=Layer(db,tr,"SOTRAMI_"+Code+"_REVESTIMIENTO",Color.FromColorIndex(ColorMethod.ByAci,1));var backing=Layer(db,tr,"SOTRAMI_"+Code+"_GEOTEXTIL",Color.FromRgb(130,130,130));
 var ms=(BlockTableRecord)tr.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(db),OpenMode.ForRead);var model=ms.Cast<ObjectId>().Select(id=>tr.GetObject(id,OpenMode.ForRead)).ToArray();var design=model.OfType<TinSurface>().Single(s=>s.Name==(Code=="010"?"Poza de agua":"Pozas"));int count=0;
 foreach(var pv in model.OfType<CivilProfileView>()){var b=pv.GeometricExtents;var location=ToPaper(profile,new Point2d((b.MinPoint.X+b.MaxPoint.X)/2,(b.MinPoint.Y+b.MaxPoint.Y)/2));if(location.X<30||location.X>600||location.Y<100||location.Y>350)continue;count++;var style=(ProfileViewStyle)tr.GetObject(pv.StyleId,OpenMode.ForWrite);foreach(var component in new[]{ProfileViewDisplayStyleType.GridHorizontalMajor,ProfileViewDisplayStyleType.GridHorizontalMinor,ProfileViewDisplayStyleType.GridVerticalMajor,ProfileViewDisplayStyleType.GridVerticalMinor}){var display=style.GetDisplayStylePlan(component);display.Color=Color.FromRgb(185,185,185);display.Lineweight=LineWeight.LineWeight005;}
 if(Code=="008")continue;var alignment=(CivilAlignment)tr.GetObject(pv.AlignmentId,OpenMode.ForRead);var segment=new List<Point2d>();int sampled=0;for(double station=pv.StationStart;station<=pv.StationEnd+.00001;station+=.1){double x=0,y=0;alignment.PointLocation(Math.Min(station,pv.StationEnd),0,ref x,ref y);if(!Inside(new Point2d(x,y),rim)){if(segment.Count>1)Liner(tr,ps,segment,liner,backing,anno);segment.Clear();continue;}double z=design.FindElevationAtXY(x,y),vx=0,vy=0;if(!pv.FindXYAtStationAndElevation(station,z,ref vx,ref vy))throw new InvalidOperationException("No se puede proyectar el revestimiento a la sección");segment.Add(ToPaper(profile,new Point2d(vx,vy)));sampled++;}if(segment.Count>1)Liner(tr,ps,segment,liner,backing,anno);if(sampled<2)throw new InvalidOperationException("La sección no atraviesa la coronación "+pv.Name);logs.Add("REVESTIMIENTO "+pv.Name+" puntos proyectados desde TIN="+sampled);}
 if(count!=2)throw new InvalidOperationException("Se esperaban dos secciones visibles: "+count);Text(tr,ps,"ESPESORES DE REVESTIMIENTO REPRESENTADOS ESQUEMÁTICAMENTE. VER DETALLES.",315,100,1.8,anno,0,550);
 var imageId=RasterImageDef.GetImageDictionary(db);if(!imageId.IsNull){var images=(DBDictionary)tr.GetObject(imageId,OpenMode.ForRead);foreach(DBDictionaryEntry pair in images){var d=tr.GetObject(pair.Value,OpenMode.ForRead) as RasterImageDef;if(d==null)continue;var file=Path.GetFileName(d.SourceFileName);if(File.Exists(Path.Combine(outdir,"Assets",file))){d.UpgradeOpen();d.SourceFileName=Path.Combine(@"C:\Users\Cesar Ugaz\Pictures\trabajo para code\ENTREGA_FINAL_4_PLANOS_2026-10-27\Assets",file);d.Load();logs.Add("IMAGEN LOCAL "+file);}}}
 foreach(ObjectId id in ps){var e=tr.GetObject(id,OpenMode.ForRead);if(e.IsErased)continue;if(e is MText m&&(m.Text.Contains("NORCOBRE")||m.Text.Contains("19m3")||m.Text.Contains("XXXX")))throw new InvalidOperationException("Texto de referencia sin adaptar");if(e is BlockReference br)foreach(ObjectId aid in br.AttributeCollection){var a=(AttributeReference)tr.GetObject(aid,OpenMode.ForRead);if(a.TextString.Contains("XXXX"))throw new InvalidOperationException("Texto provisional "+a.Tag);}}
 var after=ModelSignature(db,tr);if(!before.SequenceEqual(after))throw new InvalidOperationException("Objetos Civil alterados");logs.Add("CIVIL ORIGINAL: "+before.Count+" objetos, mismos identificadores y tipos");logs.Add("DOS SECCIONES NATIVAS: geometría, cotas y bandas originales conservadas");logs.Add("GRILLA: coordenadas WGS84 / UTM 18S, proyección de cámara verificada");logs.Add("CÓMPUTOS: geometría TIN, cobertura 100%, malla de 0.25 m, sin factores");tr.Commit();}
 doc.Editor.Regen();Plot(db,Path.Combine(outdir,"1107.001.00.14-200-14-P-"+Code+"-TERMINADO.pdf"));db.SaveAs(Path.Combine(outdir,"1107.001.00.14-200-14-P-"+Code+"-TERMINADO.dwg"),DwgVersion.Current);File.WriteAllLines(Path.Combine(outdir,"VERIFICACION-"+Code+".txt"),logs);doc.Editor.WriteMessage("\nFOURFINAL_DONE "+Code+"\n");}
 [CommandMethod("FOURVERIFY")]
 public void Verify(){System.Diagnostics.Process.GetCurrentProcess().PriorityClass=System.Diagnostics.ProcessPriorityClass.BelowNormal;var doc=App.DocumentManager.MdiActiveDocument;var db=doc.Database;var log=new List<string>();using(var tr=db.TransactionManager.StartTransaction()){var expected=File.ReadAllLines(Path.Combine(Root,"Informes","civil-"+Code+".txt"));var actual=ModelSignature(db,tr);if(!expected.SequenceEqual(actual))throw new InvalidOperationException("Identificadores Civil distintos después de reabrir");log.Add("REAPERTURA DWG: objetos Civil iguales a la fuente ("+actual.Count+")");foreach(ObjectId id in CivilDocument.GetCivilDocument(db).GetSurfaceIds()){var surface=(TinSurface)tr.GetObject(id,OpenMode.ForRead);if(surface.Name!="TERRENO EXISTENTE"&&surface.Name!=(Code=="010"?"Poza de agua":"Pozas"))continue;int count=surface.GetTriangles(false).Count;if(count==0||surface.IsReferenceObject&&!surface.IsReferenceValid)throw new InvalidOperationException("Superficie no disponible "+surface.Name);log.Add("TIN VÁLIDO "+surface.Name+" TRIÁNGULOS="+count);}
 var imageId=RasterImageDef.GetImageDictionary(db);if(!imageId.IsNull)foreach(DBDictionaryEntry pair in (DBDictionary)tr.GetObject(imageId,OpenMode.ForRead)){var d=tr.GetObject(pair.Value,OpenMode.ForRead) as RasterImageDef;if(d==null)continue;if(!File.Exists(d.SourceFileName))throw new InvalidOperationException("Imagen no localizada "+d.SourceFileName);log.Add("IMAGEN LOCALIZADA "+d.SourceFileName+" CARGADA="+d.IsLoaded);}
 var layout=(Layout)tr.GetObject(LayoutManager.Current.GetLayoutId(LayoutName),OpenMode.ForRead);var ps=(BlockTableRecord)tr.GetObject(layout.BlockTableRecordId,OpenMode.ForRead);foreach(ObjectId id in ps){var e=tr.GetObject(id,OpenMode.ForRead);if(e is MText m&&(m.Text.Contains("NORCOBRE")||m.Text.Contains("XXXX")))throw new InvalidOperationException("Texto provisional");if(e is BlockReference br)foreach(ObjectId aid in br.AttributeCollection){var a=(AttributeReference)tr.GetObject(aid,OpenMode.ForRead);if(a.TextString.Contains("XXXX"))throw new InvalidOperationException("Atributo provisional");if(a.Tag=="DRAWING_NO"&&a.TextString!="1107.001.00.14-200-14-P-"+Code)throw new InvalidOperationException("Código de plano incorrecto");}}
 log.Add("PRESENTACIÓN VERIFICADA: "+LayoutName);}
 File.WriteAllLines(Path.Combine(Root,"EntregaFinal","REAPERTURA-"+Code+".txt"),log);doc.Editor.WriteMessage("\nFOURVERIFY_DONE "+Code+"\n");}
 [CommandMethod("FOURPOLISH")]
 public void Polish(){System.Diagnostics.Process.GetCurrentProcess().PriorityClass=System.Diagnostics.ProcessPriorityClass.BelowNormal;var doc=App.DocumentManager.MdiActiveDocument;var db=doc.Database;LayoutManager.Current.CurrentLayout=LayoutName;var logs=new List<string>();using(var tr=db.TransactionManager.StartTransaction()){var before=ModelSignature(db,tr);var layout=(Layout)tr.GetObject(LayoutManager.Current.GetLayoutId(LayoutName),OpenMode.ForRead);var ps=(BlockTableRecord)tr.GetObject(layout.BlockTableRecordId,OpenMode.ForRead);var entities=ps.Cast<ObjectId>().Select(id=>tr.GetObject(id,OpenMode.ForRead)).OfType<Entity>().ToArray();var v=entities.OfType<Viewport>().Single(p=>p.Width>560&&p.Width<580&&p.CenterPoint.Y<350);var hidden=Layer(db,tr,"SOTRAMI_VENTANAS_NO_IMPRIMIR",Color.FromColorIndex(ColorMethod.ByAci,6));((LayerTableRecord)tr.GetObject(hidden,OpenMode.ForWrite)).IsPlottable=false;v.UpgradeOpen();v.LayerId=hidden;
 var model=(BlockTableRecord)tr.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(db),OpenMode.ForRead);var views=model.Cast<ObjectId>().Select(id=>tr.GetObject(id,OpenMode.ForRead)).OfType<CivilProfileView>().Select(p=>new{pv=p,b=p.GeometricExtents}).Select(p=>new{p.pv,p.b,center=ToPaper(v,new Point2d((p.b.MinPoint.X+p.b.MaxPoint.X)/2,(p.b.MinPoint.Y+p.b.MaxPoint.Y)/2))}).Where(p=>p.center.X>30&&p.center.X<600&&p.center.Y>100&&p.center.Y<350).OrderBy(p=>p.center.X).ToArray();
 foreach(var ml in entities.OfType<MLeader>()){if(ml.Layer!="SOTRAMI_"+Code+"_DETALLES"||ml.ContentType!=ContentType.MTextContent)continue;using(var m=ml.MText){if(!m.Text.StartsWith("GEOMEMBRANA"))continue;var target=ml.GetFirstVertex((int)ml.GetLeaderLineIndexes((int)ml.GetLeaderIndexes()[0])[0]);var selected=views.OrderBy(p=>Math.Abs(p.center.X-target.X)).First();var bottom=ToPaper(v,new Point2d(selected.b.MinPoint.X,selected.b.MinPoint.Y));var text=new Point3d(bottom.X+12,bottom.Y+10,0);ml.UpgradeOpen();m.TextHeight=2.2;m.BackgroundFill=true;m.UseBackgroundColor=true;m.BackgroundScaleFactor=1.1;m.Location=text;ml.MText=m;ml.TextHeight=2.2;ml.TextLocation=text;foreach(int leader in ml.GetLeaderIndexes())foreach(int line in ml.GetLeaderLineIndexes(leader))ml.SetLastVertex(line,new Point3d(text.X,text.Y-2,0));logs.Add("LLAMADO DE REVESTIMIENTO DESPEJADO "+ml.Handle);}}
